import type { ToastLocalContextType, ToastProps } from "./toast.types";

import React, { forwardRef, useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Close as DefaultCloseIcon, Info as InfoIcon } from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";
import { usePortalContainer } from "@hooks/use-portal-container";

import { ToastClasses, StyledToast } from "./toast.styles";
import { ToastLocalContext, useToastContext } from "./hooks/use-local-toast";

const ToastRoot = forwardRef<HTMLDivElement, ToastProps>(
  (
    {
      autoHideDuration,
      className,
      clickToDismiss,
      onOpenChange,
      onClose,
      variant = "default",
      children,
      show: showProp,
      position = "bottom-start",
      disablePortal = false,
      containerElement,
      ...props
    }: ToastProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const [show, setShow] = useState(showProp);
    const [mounted, setMounted] = useState(false);
    const { resolvedContainer, isScoped } = usePortalContainer(containerElement);
    const rootClasses = clsx(ToastClasses.root, className, {
      [ToastClasses.root]: true,
      [ToastClasses.slideIn]: show,
      [ToastClasses.topStart]: position === "top-start",
      [ToastClasses.topCenter]: position === "top-center",
      [ToastClasses.topEnd]: position === "top-end",
      [ToastClasses.bottomStart]: position === "bottom-start",
      [ToastClasses.bottomCenter]: position === "bottom-center",
      [ToastClasses.bottomEnd]: position === "bottom-end",
      [ToastClasses.clickToDismiss]: clickToDismiss,
    });

    const handleClose = useCallback(() => {
      setShow(false);
      onOpenChange?.(false);
      onClose?.();
    }, [onOpenChange, onClose]);

    const handleKeyDown = useCallback(
      (event: React.KeyboardEvent<HTMLDivElement>) => {
        if (clickToDismiss && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
          handleClose();
        }
      },
      [clickToDismiss, handleClose],
    );

    useEffect(() => {
      setMounted(true);
      return () => setMounted(false);
    }, []);

    useEffect(() => {
      if (typeof showProp === "boolean" && showProp !== show) {
        setShow(showProp);
        onOpenChange?.(showProp);
      }
    }, [showProp, show, onOpenChange]);

    const handleCloseRef = useRef(handleClose);
    useEffect(() => {
      handleCloseRef.current = handleClose;
    }, [handleClose]);

    useEffect(() => {
      let timerId: NodeJS.Timeout | undefined;
      if (autoHideDuration && show) {
        timerId = setTimeout(() => handleCloseRef.current(), autoHideDuration);
      }
      return () => {
        if (timerId) {
          clearTimeout(timerId);
        }
      };
    }, [autoHideDuration, show]);

    if (!show) return null;

    const contextValue: ToastLocalContextType = {
      handleClose,
    };

    const content = (
      <ToastLocalContext.Provider value={contextValue}>
        <StyledToast
          ref={ref}
          aria-atomic="true"
          aria-hidden={!show}
          className={rootClasses}
          currentTheme={theme}
          data-textura-scoped={isScoped}
          role="alert"
          tabIndex={show && clickToDismiss ? 0 : undefined}
          variant={variant}
          onClick={show && clickToDismiss ? handleClose : undefined}
          onKeyDown={show && clickToDismiss ? handleKeyDown : undefined}
          {...props}
        >
          {show && children}
        </StyledToast>
      </ToastLocalContext.Provider>
    );

    if (disablePortal) {
      return content;
    }

    return mounted && resolvedContainer ? createPortal(content, resolvedContainer) : null;
  },
);

ToastRoot.displayName = "Toast";

const Icon: React.FC<React.HTMLAttributes<HTMLSpanElement>> = ({
  children,
  className,
  ...props
}) => {
  const iconClasses = clsx(ToastClasses.icon, className);
  return (
    <span className={iconClasses} {...props}>
      {children || <InfoIcon />}
    </span>
  );
};

Icon.displayName = "Toast.Icon";

const Message: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({
  children,
  className,
  ...props
}) => {
  const messageClasses = clsx(ToastClasses.message, className);
  return (
    <div className={messageClasses} {...props}>
      {children}
    </div>
  );
};

Message.displayName = "Toast.Message";

const CloseIconButton: React.FC<React.HTMLAttributes<HTMLButtonElement>> = ({
  children,
  className,
  "aria-label": customAriaLabel,
}) => {
  const { handleClose } = useToastContext();
  const buttonClasses = clsx(ToastClasses.closeIconButton, className);

  const commonProps = {
    "aria-label": customAriaLabel || "close current toast",
  };
  return (
    <IconButton
      buttonType="secondary"
      className={buttonClasses}
      size="sm"
      variant="inverse"
      onClick={handleClose}
      {...commonProps}
    >
      {children ? children : <DefaultCloseIcon />}
    </IconButton>
  );
};
CloseIconButton.displayName = "Toast.CloseIconButton";

const Toast = Object.assign(ToastRoot, {
  Icon,
  Message,
  CloseIconButton,
});

export default Toast;
